(async()=>{const q=load('src/lib/store/quote-quantity.ts').validateQuoteQuantity,m=load('src/lib/store/moq-quantity.ts'),money=load('src/lib/currency.ts');for(const quantity of [40,41,43,80,1000000])assert.equal(q({moq:40,sold_out:false,stock:0},quantity),null);assert.equal(q({moq:40},39).errorCode,'moq_not_met');assert.equal(q({moq:40,sold_out:true},41).errorCode,'out_of_stock');assert.equal(q({moq:40},40.5).errorCode,'invalid_quantity');assert.equal(m.stepMoqQuantity(40,40,1),41);assert.equal(m.stepMoqQuantity(41,40,-1),40);assert.equal(m.snapToMoqQuantity(43,40),43);assert.equal(m.snapToMoqQuantity(39,40),40);for(const rate of [1350,1450]){assert.equal(money.cartMeetsMinOrderUsd(999.99*rate,rate),false);assert.equal(money.cartMeetsMinOrderUsd(1000*rate,rate),false);assert.equal(money.cartMeetsMinOrderUsd(1000.01*rate,rate),true);}const action=load('src/app/actions/checkout.ts').submitQuoteRequest,f=new FormData();Object.entries({purchase_purpose:'retail',sales_channel:'amazon',sales_country:'US',sales_details:'https://www.amazon.com/stores/example',company_name:'Test',contact_name:'Buyer',email:'test@example.com',country:'US',confirm_details:'on'}).forEach(([k,v])=>f.set(k,v));for(role of ['customer','business','admin'])for(total of [999*1350,1000*1350])assert.equal((await action({},f)).error,'minOrderUsd');assert.equal(creates,0);total=1000.01*1350;assert.equal((await action({},f)).error,'errors.orderCreateFailed');assert.equal(creates,1);assert.equal(verifiedCalls,7);assert.equal(saves,1);assert.deepEqual(Object.keys(savedProfile),['purchase_profile']);assert.equal(savedProfile.purchase_profile.salesChannel,'amazon');saveFails=true;assert.equal((await action({},f)).error,'saveFailed');assert.equal(creates,1);f.delete('sales_channel');assert.equal((await action({},f)).error,'channelRequired');assert.equal(saves,2);const sort=load('src/lib/store/external-best-sellers.ts').sortExternalBestSellers,selection=require('../src/data/curated-best-sellers.json');assert.equal(selection.skus.length,12);const pool=selection.skus.map(sku=>({sku,sold_out:false})).reverse();assert.deepEqual(sort(pool).map(x=>x.sku),selection.skus);assert.equal(pool[0].sku,selection.skus.at(-1));pool.find(x=>x.sku===selection.skus[0]).sold_out=true;assert.equal(sort(pool).at(-1).sku,selection.skus[0]);console.log('PASS: MOQ minimum only; 41 and 1,000,000 accepted with stock 0; sold-out rejected; >USD1000 enforced for every role using revalidated total; external rank preserved. No emails, orders or cart writes.');})().catch(e=>{console.error(e);process.exitCode=1});
